const escapeHTML=(v:string)=>v.replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]!));
export interface GameOptions extends BattleSettings {mapPlayers:"off"|"team"|"all";language:Lang;quality:GraphicsQuality;sensitivity:number;volume:number;musicVolume:number;effectsVolume:number;ambientVolume:number;fov:number;killTicketPenalty:number;renderScale:number}
export const defaults:GameOptions={mapPlayers:'team',mode:'conquest',size:32,difficulty:'easy',aiProfile:'regular',tickets:500,killTicketPenalty:1,language:'zh',quality:'high',sensitivity:.22,volume:.4,musicVolume:.76,effectsVolume:.85,ambientVolume:.25,fov:79,renderScale:1};
export function savedOptions():GameOptions{
 try{const data=JSON.parse(localStorage.getItem('ironfront-options')||'{}') as Partial<GameOptions>;const result={...defaults,...data};if(!localStorage.getItem('ironfront-balance-013')){result.difficulty='easy';localStorage.setItem('ironfront-balance-013','1');}if(data.musicVolume===.36&&!localStorage.getItem('ironfront-mix-010')){result.musicVolume=.76;localStorage.setItem('ironfront-mix-010','1');}
  if(!['conquest','breakthrough'].includes(result.mode??''))result.mode='conquest';if(![8,16,32,64].includes(result.size))result.size=32;if(![300,500,800].includes(result.tickets))result.tickets=500;
  if(!['easy','normal','hard'].includes(result.difficulty))result.difficulty='normal';if(!['regular','elite'].includes(result.aiProfile??''))result.aiProfile='regular';if(!['en','zh'].includes(result.language))result.language='zh';
  if(!['low','medium','high'].includes(result.quality))result.quality='high';if(![0,1,2].includes(result.killTicketPenalty))result.killTicketPenalty=1;
  delete result.vehicleLimit;if(!['off','team','all'].includes(result.mapPlayers))result.mapPlayers='team';result.renderScale=Math.max(.5,Math.min(1.25,Number(result.renderScale)||1));result.fov=Math.max(65,Math.min(100,Number(result.fov)||79));result.sensitivity=Math.max(.07,Math.min(.65,Number(result.sensitivity)||.22));result.volume=Math.max(0,Math.min(1,Number(result.volume)||0));for(const key of ['musicVolume','effectsVolume','ambientVolume'] as const)result[key]=Math.max(0,Math.min(1,Number.isFinite(Number(result[key]))?Number(result[key]):defaults[key]));return result;
 }catch{return {...defaults}}
}
