 private supportTarget='C';private deploymentSelected='BASE';private damageUntil=0;private damageAngle=0;
 resetBattleState(){this.notices=[];this.lastHud=0;this.supportTarget='C';this.killfeed.innerHTML='';this.hud.classList.remove('scoped','aiming','firing','hurt');this.tactical.classList.add('hidden');this.scoreboard.classList.add('hidden');this.debug.classList.add('hidden')}
 private roomForm:{address:string;code:string;ai:boolean;team:string}|null=null;
