 private intentName(intent:string){if(this.settings.language==='zh')return ({ATTACK:'进攻',DEFEND:'防守',FLANK:'侧翼',REINFORCE:'增援'} as Record<string,string>)[intent]??intent;return intent}
 private opt<T extends string|number>(value:T,label:string,selected:T){return `<option value="${value}" ${value===selected?'selected':''}>${label}</option>`}
 private battlePanel(){const t=(k:keyof typeof messages.en)=>this.text(k);return `<div class="settings-title">${t('settings')}</div><div class="form-grid"><label>玩法 / GAME MODE<select id="setup-mode">${this.opt('conquest','征服 / Conquest',this.settings.mode??'conquest')}${this.opt('breakthrough','前线推进 / Breakthrough',this.settings.mode??'conquest')}</select></label><label>${t('size')}<select id="setup-size">${this.opt(8,'8 vs 8',this.settings.size)}${this.opt(16,'16 vs 16',this.settings.size)}${this.opt(32,'32 vs 32 · TARGET',this.settings.size)}${this.opt(64,'64 vs 64 · EXP',this.settings.size)}</select></label><label>${t('difficulty')}<select id="setup-difficulty">${this.opt('easy',t('easy'),this.settings.difficulty)}${this.opt('normal',t('normal'),this.settings.difficulty)}${this.opt('hard',t('hard'),this.settings.difficulty)}</select></label><label>AI 小队 / SQUAD PROFILE<select id="setup-ai-profile">${this.opt('regular','常规小队 / REGULAR',this.settings.aiProfile??'regular')}${this.opt('elite','精锐小队 / ELITE',this.settings.aiProfile??'regular')}</select></label><label>地图显示玩家<select id="setup-player-map">${this.opt('off','关闭',this.settings.mapPlayers)}${this.opt('team','仅相同阵营',this.settings.mapPlayers)}${this.opt('all','全部玩家',this.settings.mapPlayers)}</select></label><label>${t('tickets')}<select id="setup-tickets">${this.opt(300,'300',this.settings.tickets)}${this.opt(500,'500',this.settings.tickets)}${this.opt(800,'800',this.settings.tickets)}</select></label><label>${t('penalty')}<select id="setup-penalty">${this.opt(0,'0',this.settings.killTicketPenalty)}${this.opt(1,'1',this.settings.killTicketPenalty)}${this.opt(2,'2',this.settings.killTicketPenalty)}</select></label></div><p class="setup-note">精锐小队更重视目标与队形，不提高伤害或视野。${t('experimental')}</p>`}
