 private controlsPanel(){const rows=[['W A S D',this.settings.language==='zh'?'移动':'Move'],['MOUSE',this.settings.language==='zh'?'观察 / 瞄准':'Look / Aim'],['LMB / RMB',this.settings.language==='zh'?'开火 / 举枪瞄准':'Fire / ADS'],['SHIFT',this.settings.language==='zh'?'移动中点按滑铲 / 按住冲刺':'Tap while moving: slide / hold: sprint'],['CTRL / C',this.settings.language==='zh'?'下蹲':'Crouch'],['SPACE',this.settings.language==='zh'?'跳跃':'Jump'],['R',this.settings.language==='zh'?'换弹':'Reload'],['1 / 2',this.settings.language==='zh'?'切换武器':'Switch weapon'],['Q / G / X',this.settings.language==='zh'?'支援 / 投掷 / 装备':'Support / Grenade / Gadget'],['Z',this.settings.language==='zh'?'工程兵反装甲火箭筒':'Engineer anti-armor rocket'],['F1–F4',this.settings.language==='zh'?'载具座位（F3 调试仅限步兵）':'Vehicle seats'],['V','步兵 / 载具第一第三人称'],['B','工程兵防空导弹 · 左键发射'],['E',this.settings.language==='zh'?'进入 / 离开装甲载具':'Enter / exit armored vehicle'],['M / TAB',this.settings.language==='zh'?'战术地图 / 计分板':'Map / Scoreboard'],['F3',this.settings.language==='zh'?'开发调试':'Diagnostics']];return `<div class="settings-title">${this.text('controlsTab')}</div><div class="control-list">${rows.map(([k,v])=>`<div><kbd>${k}</kbd><span>${v}</span></div>`).join('')}</div><label class="slider-row">${this.text('sensitivity')}<input id="setup-sensitivity" type="range" min="7" max="65" value="${Math.round(this.settings.sensitivity*100)}"/><output>${this.settings.sensitivity.toFixed(2)}</output></label>`}
 private panel(){if(this.menuTab==='controls')return this.controlsPanel();if(this.menuTab==='graphics')return this.graphicsPanel();if(this.menuTab==='audio')return this.audioPanel();return this.battlePanel()}
 private saveSettings(){const q=(s:string)=>this.modal.querySelector<HTMLInputElement|HTMLSelectElement>(s),num=(s:string,fallback:number)=>Number(q(s)?.value??fallback);
  if(q('#setup-player-map'))this.settings.mapPlayers=q('#setup-player-map')!.value as GameOptions['mapPlayers'];if(q('#setup-mode'))this.settings.mode=q('#setup-mode')!.value as GameOptions['mode'];if(q('#setup-size'))this.settings.size=num('#setup-size',this.settings.size) as GameOptions['size'];if(q('#setup-difficulty'))this.settings.difficulty=q('#setup-difficulty')!.value as GameOptions['difficulty'];if(q('#setup-ai-profile'))this.settings.aiProfile=q('#setup-ai-profile')!.value as GameOptions['aiProfile'];if(q('#setup-tickets'))this.settings.tickets=num('#setup-tickets',this.settings.tickets);if(q('#setup-penalty'))this.settings.killTicketPenalty=num('#setup-penalty',this.settings.killTicketPenalty);
  if(q('#setup-quality'))this.settings.quality=q('#setup-quality')!.value as GraphicsQuality;if(q('#setup-volume'))this.settings.volume=num('#setup-volume',this.settings.volume*100)/100;if(q('#setup-sensitivity'))this.settings.sensitivity=num('#setup-sensitivity',this.settings.sensitivity*100)/100;if(q('#setup-fov'))this.settings.fov=num('#setup-fov',this.settings.fov);
  for(const key of ['musicVolume','effectsVolume','ambientVolume'] as const)if(q(`#setup-${key}`))this.settings[key]=num(`#setup-${key}`,this.settings[key]*100)/100;
  this.persist();this.onChange(this.settings);this.modal.querySelectorAll<HTMLInputElement>('input[type="range"]').forEach(input=>{const out=input.parentElement?.querySelector('output');if(out)out.textContent=['setup-volume','setup-musicVolume','setup-effectsVolume','setup-ambientVolume'].includes(input.id)?`${input.value}%`:input.id==='setup-fov'?`${input.value}°`:(Number(input.value)/100).toFixed(2)})
 }
