  const buttons=(map:boolean)=>locations.filter((l,i)=>!map||l.kind!=='vehicle'||!locations.slice(0,i).some(o=>o.kind==='vehicle'&&o.id.split('-')[1]===l.id.split('-')[1])).map(l=>`<button data-location="${l.id}" class="spawn-location ${l.available?'safe':'blocked'} ${l.id===this.deploymentSelected?'selected':''}" ${map?`style="left:${(l.at.x+MAP_SIZE/2)/MAP_SIZE*100}%;top:${(l.at.z+MAP_SIZE/2)/MAP_SIZE*100}%"`:''} data-unavailable="${!l.available}"><strong>${map?(l.kind==='squad'?'♟':l.kind==='beacon'?'⚑':l.kind==='vehicle'?this.vehicleIcon(battle.vehicles[Number(l.id.split('-')[1])]!.kind):l.id==='BASE'?'⌂':'⚑'):l.name}</strong>${map?'':`<small>${l.reason}</small>`}</button>`).join('');
