  for(const button of this.modal.querySelectorAll<HTMLElement>('[data-location]')){const l=locations.find(l=>l.id===button.dataset.location)!;button.classList.toggle('safe',l.available);button.classList.toggle('blocked',!l.available);button.classList.toggle('selected',l.id===this.deploymentSelected);button.setAttribute('aria-pressed',String(l.id===this.deploymentSelected));button.setAttribute('aria-label',l.name+' · '+l.reason);const status=button.querySelector('small');if(status)status.textContent=l.reason;if(button.parentElement===markers){button.title=l.name+' · '+l.reason;}}
  const bounds=markers.getBoundingClientRect(),placed:{x:number;y:number;w:number;h:number}[]=[];for(const button of markers.querySelectorAll<HTMLElement>('button')){const l=locations.find(l=>l.id===button.dataset.location)!,rect=button.getBoundingClientRect(),w=(rect.width+8)/Math.max(1,bounds.width)*100,h=(rect.height+8)/Math.max(1,bounds.height)*100,baseX=(l.at.x+MAP_SIZE/2)/MAP_SIZE*100,baseY=(l.at.z+MAP_SIZE/2)/MAP_SIZE*100;let x=baseX,y=baseY;const overlaps=()=>placed.some(p=>Math.abs(p.x-x)<(p.w+w)/2&&Math.abs(p.y-y)<(p.h+h)/2);for(let i=0;i<500&&overlaps();i++){const a=i*2.4,rr=3+Math.sqrt(i)*2;x=Math.max(w/2,Math.min(100-w/2,baseX+Math.cos(a)*rr));y=Math.max(h/2,Math.min(100-h/2,baseY+Math.sin(a)*rr));}placed.push({x,y,w,h});button.style.left=x+'%';button.style.top=y+'%';}
  const current=locations.find(l=>l.id===this.deploymentSelected),deploy=this.modal.querySelector<HTMLButtonElement>('#deploy-respawn')!;deploy.disabled=waiting>0||!current?.available;deploy.textContent=waiting>0?`复活准备 ${waiting.toFixed(1)}s`:'部署 / DEPLOY';this.modal.querySelector('#deployment-reason')!.textContent=current?`${current.name} · ${current.reason}`:'位置已失效，请重新选择';
